return ['domain'=>'simple-ldap-login','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'pl_PL','project-id-version'=>'Simple LDAP Login 2.0.0','pot-creation-date'=>'2026-10-30T15:26:17+00:00','po-revision-date'=>'2026-10-30T15:26:17+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Simple LDAP Login'=>'Simple LDAP Login','https://github.com/clifgriffin/simple-ldap-login'=>'https://github.com/clifgriffin/simple-ldap-login','Connect WordPress accounts to Active Directory or OpenLDAP.'=>'Połącz konta WordPress z Active Directory lub OpenLDAP.','Clif Griffin Development Inc.'=>'Clif Griffin Development Inc.','https://clifgriffin.com'=>'https://clifgriffin.com','User data'=>'Dane użytkownika','Single sign-on'=>'Jednolity dostęp (SSO)','Custom user fields'=>'Niestandardowe pola użytkownika','Copy LDAP fields, such as phone number or department, to WordPress at login. Your theme or other plugins can use these values.'=>'Kopiuj pola LDAP, takie jak numer telefonu lub dział, do WordPressa podczas logowania. Twoja motywacja lub inne wtyczki mogą używać tych wartości.','Field mappings'=>'Mapowanie pól','One mapping per line: LDAP attribute:WordPress meta key:type. Example: %1$s. Types: %2$s or %3$s.'=>'Jedno mapowanie na linię: atrybut LDAP:klucz meta WordPress:typ. Przykład: %1$s. Typy: %2$s lub %3$s.','Custom field storage'=>'Przechowywanie niestandardowych pól','Leave the defaults unless your integration uses different user meta keys.'=>'Zostaw domyślne, chyba że Twoja integracja używa innych kluczy meta użytkownika.','LDAP value suffix'=>'Sufiks wartości LDAP','Stores the LDAP value, such as phone_ldap.'=>'Przechowuje wartość LDAP, taką jak phone_ldap.','WordPress value suffix'=>'Sufiks wartości WordPress','Stores the editable WordPress value, such as phone_wp.'=>'Przechowuje edytowalną wartość WordPress, taką jak phone_wp.','Single sign-on (SSO)'=>'Jednolity dostęp (SSO)','Sign users in to WordPress after your web server authenticates them.'=>'Zaloguj użytkowników do WordPressa po uwierzytelnieniu ich przez serwer WWW.','Enable single sign-on'=>'Włącz jednolity proces logowania','Users do not need a second login for WordPress.'=>'Użytkownicy nie potrzebują drugiego logowania do WordPressa.','Configure your web server to authenticate users and set REMOTE_USER. Enter an LDAP search account on Connection.'=>'Skonfiguruj swój serwer WWW, aby uwierzytelniał użytkowników i ustawił REMOTE_USER. Wprowadź konto wyszukiwania LDAP w sekcji Połączenie.','Do not copy browser headers into REMOTE_USER. Block access that bypasses web server authentication.'=>'Nie kopiuj nagłówków przeglądarki do REMOTE_USER. Zablokuj dostęp, który omija uwierzytelnianie serwera WWW.','Web server authentication'=>'Uwierzytelnienie serwera WWW','REMOTE_USER is present.'=>'REMOTE_USER jest obecny.','REMOTE_USER is missing. Check the web server configuration.'=>'REMOTE_USER jest brakujący. Sprawdź konfigurację serwera WWW.','The update was stopped. Activate Simple LDAP Login Pro to restore LDAP login.'=>'Aktualizacja została zatrzymana. Aktywuj Simple LDAP Login Pro, aby przywrócić logowanie LDAP.','Update blocked: This package does not include all Pro files. To install Free, deactivate the plugin first. Your installed files and settings are unchanged.'=>'Aktualizacja zablokowana: Ten pakiet nie zawiera wszystkich plików Pro. Aby zainstalować wersję Free, najpierw dezaktywuj wtyczkę. Twoje zainstalowane pliki i ustawienia pozostają niezmienione.','WordPress could not reactivate the plugin.'=>'WordPress nie mógł ponownie aktywować wtyczki.','Simple LDAP Login needs PHP 8.1 or later.'=>'Simple LDAP Login wymaga PHP 8.1 lub nowszego.','Plugin files are missing. Reinstall Simple LDAP Login from the release ZIP.'=>'Brakuje plików wtyczki. Zainstaluj ponownie Simple LDAP Login z pliku ZIP wydania.','You do not have permission to change these settings.'=>'Nie masz uprawnień do zmiany tych ustawień.','The settings scope has changed. Open the settings page and try again.'=>'Zakres ustawień uległ zmianie. Otwórz stronę ustawień i spróbuj ponownie.','You do not have permission to view these settings.'=>'Nie masz uprawnień do przeglądania tych ustawień.','Network settings'=>'Ustawienia sieciowe','Site settings'=>'Ustawienia witryny','LDAP login settings'=>'Ustawienia logowania LDAP','Connect to LDAP, then test a login before enabling authentication.'=>'Połącz z LDAP, a następnie przetestuj logowanie przed włączeniem uwierzytelniania.','LDAP login and SSO are disabled by SLL_DISABLE_LDAP in wp-config.php.'=>'Logowanie LDAP i SSO są wyłączone przez SLL_DISABLE_LDAP w wp-config.php.','Your saved settings use SSO or custom user fields. Install Simple LDAP Login Pro to use these features. Your settings are kept.'=>'Twoje zapisane ustawienia używają SSO lub niestandardowych pól użytkowników. Zainstaluj Simple LDAP Login Pro, aby korzystać z tych funkcji. Twoje ustawienia są zachowane.','The saved LDAP search password cannot be read. Enter it again on the Connection tab.'=>'Zapisane hasło wyszukiwania LDAP nie może być odczytane. Wprowadź je ponownie na karcie Połączenie.','PHP LDAP is missing. Ask your host to install it before enabling LDAP login.'=>'Brak PHP LDAP. Poproś swojego hosta o zainstalowanie go przed włączeniem logowania LDAP.','LDAP passwords are sent without encryption. Use StartTLS or LDAPS if your server supports it.'=>'Hasła LDAP są wysyłane bez szyfrowania. Użyj StartTLS lub LDAPS, jeśli twój serwer to obsługuje.','Save settings'=>'Zapisz ustawienia','Settings on other tabs are kept.'=>'Ustawienia na innych zakładkach są zachowane.','LDAP connection'=>'Połączenie LDAP','LDAP login'=>'Logowanie LDAP','Enable LDAP authentication.'=>'Włącz uwierzytelnianie LDAP.','Directory type'=>'Typ katalogu','Active Directory'=>'Active Directory','OpenLDAP / other LDAP directory'=>'OpenLDAP / inny katalog LDAP','LDAP servers'=>'Serwery LDAP','One hostname or IP address per line. Servers are tried in order.'=>'Jedna nazwa hosta lub adres IP na linię. Serwery są próbowane w kolejności.','Base DN'=>'Podstawowy DN','Where to search for users. Example: DC=example,DC=org.'=>'Gdzie szukać użytkowników. Przykład: DC=example,DC=org.','Username suffix'=>'Sufiks nazwy użytkownika','Added to usernames without a domain. Example: @example.org.'=>'Dodawany do nazw użytkowników bez domeny. Przykład: @example.org.','Windows domain'=>'Domena Windows','Short domain name, such as EXAMPLE. Takes priority over the username suffix.'=>'Krótka nazwa domeny, taka jak EXAMPLE. Ma priorytet nad sufiksem nazwy użytkownika.','Connection security'=>'Bezpieczeństwo połączenia','TLS requires a trusted server certificate.'=>'TLS wymaga zaufanego certyfikatu serwera.','StartTLS (recommended)'=>'StartTLS (zalecane)','LDAPS'=>'LDAPS','Unencrypted LDAP'=>'Niezaszyfrowany LDAP','Unencrypted LDAP requires permission on the Advanced tab.'=>'Niezaszyfrowany LDAP wymaga zezwolenia na zakładce Zaawansowane.','Port'=>'Port','389 for StartTLS; 636 for LDAPS.'=>'389 dla StartTLS; 636 dla LDAPS.','Search subfolders'=>'Szukaj podfolderów','Search all organizational units below the Base DN.'=>'Szukaj wszystkich jednostek organizacyjnych poniżej podstawowego DN.','LDAP search account'=>'Konto wyszukiwania LDAP','An LDAP account with read access to users and groups.'=>'Konto LDAP z dostępem do odczytu użytkowników i grup.','Search account'=>'Konto wyszukiwania','LDAP bind DN or account name.'=>'DN lub nazwa konta do powiązania LDAP.','Search account password'=>'Hasło konta wyszukiwania','Leave blank to keep the saved password.'=>'Pozostaw puste, aby zachować zapisane hasło.','Login rules'=>'Zasady logowania','Require LDAP passwords'=>'Wymagaj haseł LDAP','Block WordPress passwords except for recovery access.'=>'Zablokuj hasła WordPress z wyjątkiem dostępu do odzyskiwania.','Local recovery access'=>'Lokalny dostęp do odzyskiwania','Selected administrators'=>'Wybrani administratorzy','All super administrators (legacy)'=>'Wszyscy superadministratorzy (legacy)','All administrators (legacy)'=>'Wszyscy administratorzy (legacy)','Off'=>'Wyłączone','Choose who can use a WordPress password when LDAP passwords are required.'=>'Wybierz, kto może używać hasła WordPress, gdy wymagane są hasła LDAP.','Automatic account creation'=>'Automatyczne tworzenie konta','Create a WordPress account on the first successful LDAP login.'=>'Utwórz konto WordPress przy pierwszym udanym logowaniu LDAP.','Default role'=>'Domyślna rola','For new accounts only.'=>'Tylko dla nowych kont.','Required groups'=>'Wymagane grupy','One group name per line. Users must belong to at least one. Leave blank to allow all LDAP users.'=>'Jedna nazwa grupy na linię. Użytkownicy muszą należeć do co najmniej jednej. Pozostaw puste, aby zezwolić wszystkim użytkownikom LDAP.','Recovery accounts'=>'Konta odzyskiwania','For Selected administrators only. Use separate local accounts with WordPress passwords. Hold Ctrl or Command to select multiple accounts.'=>'Tylko dla wybranych administratorów. Użyj oddzielnych lokalnych kont z hasłami WordPress. Przytrzymaj Ctrl lub Command, aby wybrać wiele kont.','Connection options'=>'Opcje połączenia','Change these only if the default values do not work with your directory.'=>'Zmień te ustawienia tylko wtedy, gdy domyślne wartości nie działają z twoim katalogiem.','LDAP timeout (seconds)'=>'Limit czasu LDAP (sekundy)','Maximum wait for an LDAP operation. Default: 5 seconds.'=>'Maksymalny czas oczekiwania na operację LDAP. Domyślnie: 5 sekund.','Login attribute'=>'Atrybut logowania','Attribute used to find users. Default: uid.'=>'Atrybut używany do znajdowania użytkowników. Domyślnie: uid.','Allow unencrypted LDAP'=>'Zezwól na niezaszyfrowany LDAP','Allow passwords to be sent without encryption.'=>'Zezwól na wysyłanie haseł bez szyfrowania.','Group search'=>'Wyszukiwanie grupy','Group base DN'=>'Podstawowy DN grupy','Leave blank to use the user Base DN.'=>'Pozostaw puste, aby użyć podstawowego DN użytkownika.','Group name attribute'=>'Atrybut nazwy grupy','Default: cn.'=>'Domyślnie: cn.','Group member attribute'=>'Atrybut członka grupy','Default: memberUid. Use member or uniqueMember if groups store user DNs.'=>'Domyślnie: memberUid. Użyj member lub uniqueMember, jeśli grupy przechowują DN użytkowników.','Profile attributes'=>'Atrybuty profilu','LDAP attributes copied to new WordPress accounts.'=>'Atrybuty LDAP kopiowane do nowych kont WordPress.','First name attribute'=>'Atrybut imienia','Last name attribute'=>'Atrybut nazwiska','Email attribute'=>'Atrybut e-mail','Website attribute'=>'Atrybut strony internetowej','Data retention'=>'Przechowywanie danych','Delete settings when removing the plugin'=>'Usuń ustawienia podczas usuwania wtyczki','Delete saved settings and LDAP credentials when WordPress deletes the plugin. Keep user accounts.'=>'Usuń zapisane ustawienia i dane uwierzytelniające LDAP, gdy WordPress usunie wtyczkę. Zachowaj konta użytkowników.','Test LDAP login'=>'Testuj logowanie LDAP','Save your settings, then run both tests. Keep this administrator session open.'=>'Zapisz swoje ustawienia, a następnie uruchom oba testy. Zachowaj tę sesję administratora otwartą.','Tests check the connection, password, and required groups. They do not create accounts or sign users in.'=>'Testy sprawdzają połączenie, hasło i wymagane grupy. Nie tworzą kont ani nie logują użytkowników.','After both tests pass, enable LDAP and try logging in from another browser.'=>'Po pomyślnym zakończeniu obu testów włącz LDAP i spróbuj zalogować się z innej przeglądarki.','Recovery'=>'Odzyskiwanie','If you are locked out, rename the simple-ldap-login folder using your hosting file manager. Log in with a WordPress administrator password, then restore the folder and correct the settings.'=>'Jeśli nie masz dostępu, zmień nazwę folderu simple-ldap-login za pomocą menedżera plików hostingu. Zaloguj się za pomocą hasła administratora WordPress, a następnie przywróć folder i popraw ustawienia.','For certificate errors, ask your host to configure the trusted LDAP certificate authority.'=>'W przypadku błędów certyfikatu poproś swojego hosta o skonfigurowanie zaufanego urzędów certyfikacji LDAP.','LDAP tests'=>'Testy LDAP','Tests use saved settings.'=>'Testy używają zapisanych ustawień.','1. Test connection'=>'1. Test połączenia','Connect to LDAP and test the search account, if set.'=>'Połącz się z LDAP i przetestuj konto wyszukiwania, jeśli jest ustawione.','Test connection'=>'Test połączenia','2. Test login'=>'2. Test logowania','Check an LDAP username, password, and group membership.'=>'Sprawdź nazwę użytkownika LDAP, hasło i członkostwo w grupie.','LDAP username'=>'Nazwa użytkownika LDAP','LDAP password'=>'Hasło LDAP','Settings saved.'=>'Ustawienia zapisane.','Connection test passed.'=>'Test połączenia zakończony sukcesem.','Cannot connect to LDAP. Check the server, port, TLS certificate, and search account.'=>'Nie można połączyć się z LDAP. Sprawdź serwer, port, certyfikat TLS i konto wyszukiwania.','LDAP login test passed. No account was created.'=>'Test logowania LDAP zakończony sukcesem. Nie utworzono konta.','LDAP login test failed. Check the username, password, and required groups.'=>'Test logowania LDAP nie powiódł się. Sprawdź nazwę użytkownika, hasło i wymagane grupy.','Could not save settings. Check the values and try again.'=>'Nie można zapisać ustawień. Sprawdź wartości i spróbuj ponownie.','Connection'=>'Połączenie','Access'=>'Dostęp','Advanced'=>'Zaawansowane','Troubleshooting'=>'Rozwiązywanie problemów','Your LDAP login is valid, but you need a WordPress account. Contact your site administrator.'=>'Twoje logowanie LDAP jest ważne, ale potrzebujesz konta WordPress. Skontaktuj się z administratorem witryny.','Your LDAP username is not a valid WordPress username. Contact your site administrator.'=>'Twoja nazwa użytkownika LDAP nie jest ważną nazwą użytkownika WordPress. Skontaktuj się z administratorem witryny.','The default WordPress role is not available. Contact your site administrator.'=>'Domyślna rola WordPress nie jest dostępna. Skontaktuj się z administratorem witryny.','Could not create your WordPress account. Contact your site administrator.'=>'Nie można utworzyć konta WordPress. Skontaktuj się z administratorem witryny.','Use your WordPress password for this recovery account.'=>'Użyj swojego hasła WordPress do tego konta odzyskiwania.','License'=>'Licencja','Get Pro'=>'Zdobądź Pro','Could not check your license. Pro features remain active. Try again on the License tab.'=>'Nie można sprawdzić twojej licencji. Funkcje Pro pozostają aktywne. Spróbuj ponownie na karcie Licencja.','Your Pro license has expired. Single sign-on and custom field updates are off. Renew your license, then select Check license on the License tab.'=>'Twoja licencja Pro wygasła. Jednolity proces logowania i aktualizacje pól niestandardowych są wyłączone. Odnów swoją licencję, a następnie wybierz Sprawdź licencję na karcie Licencja.','Activate a Pro license on the License tab to use single sign-on and custom user fields.'=>'Aktywuj licencję Pro na karcie Licencja, aby korzystać z jednolitego procesu logowania i niestandardowych pól użytkowników.','Simple LDAP Login Pro'=>'Simple LDAP Login Pro','Give staff fewer login prompts and keep user details in sync with LDAP.'=>'Daj pracownikom mniej monitów logowania i synchronizuj dane użytkowników z LDAP.','Let staff open WordPress without another login prompt. Requires authentication on your web server, such as Kerberos or NTLM.'=>'Pozwól pracownikom otworzyć WordPress bez kolejnego monitu logowania. Wymaga uwierzytelnienia na twoim serwerze WWW, takiego jak Kerberos lub NTLM.','Copy phone numbers, departments, and other LDAP fields to WordPress at login. Use these values in your theme or other plugins.'=>'Kopiuj numery telefonów, działy i inne pola LDAP do WordPressa podczas logowania. Użyj tych wartości w swoim motywie lub innych wtyczkach.','View plans'=>'Zobacz plany','Open checkout in a new tab'=>'Otwórz kasę w nowej karcie','Plans and checkout use PaidCommunities. It receives your IP address and browser details.'=>'Plany i zakupy korzystają z PaidCommunities. Otrzymuje twój adres IP i szczegóły przeglądarki.','After purchase, install the Pro ZIP from your receipt. Your LDAP settings will stay in place.'=>'Po zakupie zainstaluj plik ZIP Pro z paragonu. Twoje ustawienia LDAP pozostaną na miejscu.','License status updated.'=>'Status licencji zaktualizowany.','Could not verify the license. Check your key and connection, then try again.'=>'Nie można zweryfikować licencji. Sprawdź swój klucz i połączenie, a następnie spróbuj ponownie.','Pro license'=>'Licencja Pro','Enter the license key from your purchase receipt.'=>'Wprowadź klucz licencyjny z paragonu zakupu.','Not activated'=>'Nieaktywowane','Expired'=>'Wygasło','Inactive'=>'Nieaktywne','License status'=>'Status licencji','Active'=>'Aktywna','Data shared with PaidCommunities'=>'Dane udostępnione PaidCommunities','Activation sends your license key, site domain, plugin version, and server IP address to PaidCommunities. License checks send the same site details.'=>'Aktywacja wysyła twój klucz licencyjny, domenę witryny, wersję wtyczki i adres IP serwera do PaidCommunities. Sprawdzenia licencji wysyłają te same szczegóły witryny.','License key'=>'Klucz licencyjny','Activate license'=>'Aktywuj licencję','Deactivate license'=>'Dezaktywuj licencję','Check license'=>'Sprawdź licencję','Select a license action.'=>'Wybierz akcję licencyjną.','Activating license…'=>'Aktywowanie licencji…','Deactivating license…'=>'Dezaktywowanie licencji…','License error'=>'Błąd licencji','License updated'=>'Licencja zaktualizowana','Pro plans'=>'Plany Pro','Loading plans…'=>'Ładowanie planów…','Could not load plans. Open checkout in a new tab.'=>'Nie można załadować planów. Otwórz kasę w nowej karcie.','LDAP login failed. Check your username and password or contact your site administrator.'=>'Logowanie LDAP nie powiodło się. Sprawdź swoją nazwę użytkownika i hasło lub skontaktuj się z administratorem witryny.','Your account is not allowed to log in to this site.'=>'Twoje konto nie ma uprawnień do logowania się na tej stronie.','LDAP login is unavailable. Contact your site administrator.'=>'Logowanie przez LDAP jest niedostępne. Skontaktuj się z administratorem strony.','PHP OpenSSL is required to save the LDAP search password.'=>'PHP OpenSSL jest wymagany do zapisania hasła wyszukiwania LDAP.','Could not read or save the LDAP search password. Enter it again. If this continues, ask your host to check OpenSSL and the encryption key.'=>'Nie można odczytać ani zapisać hasła wyszukiwania LDAP. Wprowadź je ponownie. Jeśli problem będzie się powtarzał, poproś swojego dostawcę hostingu o sprawdzenie OpenSSL i klucza szyfrującego.','Select a recovery account on the Access tab, or turn local recovery access Off.'=>'Wybierz konto odzyskiwania na karcie Dostęp lub wyłącz lokalny dostęp do odzyskiwania.','Enable Allow unencrypted LDAP on the Advanced tab, or choose StartTLS or LDAPS.'=>'Włącz zezwolenie na niezaszyfrowany LDAP na karcie Zaawansowane lub wybierz StartTLS lub LDAPS.','A custom field mapping uses a protected or invalid WordPress user meta key.'=>'Mapowanie niestandardowego pola używa chronionego lub nieprawidłowego klucza meta użytkownika WordPress.','Enter a Base DN and at least one LDAP server before enabling LDAP login.'=>'Wprowadź Base DN i przynajmniej jeden serwer LDAP przed włączeniem logowania LDAP.','WordPress could not save the settings. Try again.'=>'WordPress nie mógł zapisać ustawień. Spróbuj ponownie.','LDAP protocol version'=>'Wersja protokołu LDAP','LDAP timeout'=>'Limit czasu LDAP','Check the submitted settings. No changes were saved.'=>'Sprawdź przesłane ustawienia. Żadne zmiany nie zostały zapisane.','Check %s. No changes were saved.'=>'Sprawdź %s. Żadne zmiany nie zostały zapisane.']];